import{_ as a,o as r,c as t,ao as i}from"./chunks/framework.DxOLA-qj.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Amin Alibakhshi","text":"","tagline":"Postdoctoral Fellow, Universidade da Coruña, A Coruña, Spain","actions":[{"theme":"brand","text":"Papers","link":"/papers"},{"theme":"alt","text":"GitHub","link":"https://github.com/Aminofa70"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function n(l,e,s,p,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="About" tabindex="-1">About <a class="header-anchor" href="#About" aria-label="Permalink to &quot;About {#About}&quot;">​</a></h2><p>I have been conducting scientific research since 2016, beginning during the final year of my bachelor’s degree. Over the past ten years, I have developed a strong foundation in solid mechanics, computational modeling, and numerical methods.</p><p>In 2022, I was awarded the prestigious Marie Skłodowska-Curie Fellowship to pursue my Ph.D. at the Universidad Politécnica de Madrid, Spain, where I completed my doctoral degree in 2025.</p><p>In 2026, I joined Dr. Guillermo Lorenzo’s research group at the Universidade da Coruña as a postdoctoral fellow. My current research focuses on computational biomechanics, particularly modeling deformation and cancer progression in organs such as the prostate and breast.</p><p>Most recently, I was awarded the prestigious Juan de la Cierva Fellowship, which will allow me to continue my postdoctoral research for the next three years under the supervision of Dr. Guillermo Lorenzo.</p><p>My research interests include solid mechanics, biomechanics, artificial neural networks, smart materials, finite element analysis, topology optimization, metamaterials, structural dynamics, and nonlinear vibrations. I am particularly focused on the development of numerical methods for multiphysics problems involving soft and active materials.</p><p>Beyond theoretical and applied research, I am actively involved in scientific software development. Notably, I have contributed to the following packages:</p><ul><li><p><a href="https://github.com/COMODO-research/Comodo.jl" target="_blank" rel="noreferrer">Comodo.jl</a></p></li><li><p><a href="https://github.com/Aminofa70/FerriteHyperelastic.jl" target="_blank" rel="noreferrer">FerriteHyperelastic.jl</a></p></li><li><p><a href="https://github.com/Aminofa70/PUPM.jl" target="_blank" rel="noreferrer">PUPM.jl</a></p></li><li><p><a href="https://github.com/COMODO-research/ComodoFerrite.jl" target="_blank" rel="noreferrer">ComodoFerrite.jl</a></p></li><li><p><a href="https://github.com/COMODO-research/ComodoGridap.jl" target="_blank" rel="noreferrer">ComodoGridap.jl</a></p></li><li><p><a href="https://github.com/bifurcationkit/FerriteBifurcationKit.jl" target="_blank" rel="noreferrer">FerriteBifurcationKit.jl</a></p></li><li><p><a href="https://github.com/COMODO-research/Jutopia.jl" target="_blank" rel="noreferrer">Jutopia.jl</a></p></li></ul><h2 id="Papers" tabindex="-1">Papers <a class="header-anchor" href="#Papers" aria-label="Permalink to &quot;Papers {#Papers}&quot;">​</a></h2><p>See my papers here:</p><p><a href="./papers">Papers</a></p><h2 id="GitHub" tabindex="-1">GitHub <a class="header-anchor" href="#GitHub" aria-label="Permalink to &quot;GitHub {#GitHub}&quot;">​</a></h2><p><a href="https://github.com/Aminofa70" target="_blank" rel="noreferrer">View my GitHub</a></p>',13)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
